+    fn remember_right_cursor_hint(&self, right_content: &str, cursor_column: Option<usize>) {
+        let lines = right_content.lines().collect::<Vec<_>>();
+        let Some(line) = lines.last() else {
+            self.right_cursor_hint.set(Some(VisualCursor::new(0, 0)));
+            return;
+        };
+        let line_len = line.chars().count();
+        let column = cursor_column.unwrap_or(line_len).min(line_len);
+        self.right_cursor_hint.set(Some(VisualCursor::new(
+            lines.len().saturating_sub(1),
+            column,
+        )));
+    }
+
+    fn start_visual_mode(&mut self, mode: UiMode) -> Vec<UiAction> {
+        let Some(kind) = VisualKind::from_mode(mode) else {
+            return Vec::new();
+        };
+        let cursor = self.current_visual_cursor(self.focus);
+        self.mode = mode;
+        self.visual_selection = Some(VisualSelection {
+            pane: self.focus,
+            kind,
+            anchor: cursor,
+            cursor,
+        });
+        Vec::new()
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                Vec::new()
+            }
+            UiKey::Char('v') => {
+                if self.mode == UiMode::Visual {
+                    self.clear_visual_selection();
+                } else {
+                    self.set_visual_mode(UiMode::Visual);
+                }
+                Vec::new()
+            }
+            UiKey::Char('V') => {
+                self.set_visual_mode(UiMode::VisualLine);
+                Vec::new()
+            }
+            UiKey::CtrlV => {
+                self.set_visual_mode(UiMode::VisualBlock);
+                Vec::new()
+            }
+            UiKey::Char('y') => self.copy_visual_selection(false),
+            UiKey::Char('Y') => self.copy_visual_selection(true),
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1);
+                Vec::new()
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1);
+                Vec::new()
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0);
+                Vec::new()
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0);
+                Vec::new()
+            }
+            _ => Vec::new(),
+        }
+    }
+
+    fn set_visual_mode(&mut self, mode: UiMode) {
+        let Some(kind) = VisualKind::from_mode(mode) else {
+            return;
+        };
+        if self.visual_selection.is_none() {
+            let _ = self.start_visual_mode(mode);
+            return;
+        }
+        self.mode = mode;
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        }
+    }
+
+    fn copy_visual_selection(&mut self, linewise: bool) -> Vec<UiAction> {
+        self.mode = UiMode::Command;
+        vec![UiAction::CopySelection { linewise }]
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let left_row_count = self
+            .visual_selection
+            .filter(|selection| selection.pane == PaneFocus::Left)
+            .map(|_| {
+                let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+                self.left_pane_text_lines(inner_width).len()
+            });
+
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        selection.cursor.row = offset_index(selection.cursor.row, row_delta);
+        selection.cursor.column = offset_index(selection.cursor.column, column_delta);
+        if let Some(row_count) = left_row_count
+            && row_count > 0
+        {
+            selection.cursor.row = selection.cursor.row.min(row_count - 1);
+        }
+    }
+
+    fn current_visual_cursor(&self, pane: PaneFocus) -> VisualCursor {
+        match pane {
+            PaneFocus::Left => VisualCursor::new(self.control_selected, 0),
+            PaneFocus::Right => self
+                .right_cursor_hint
+                .get()
+                .unwrap_or(VisualCursor::new(0, 0)),
+        }
+    }
+
+    fn visual_text_lines(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => {
+                if self.layout().left_width == 0 {
+                    return Vec::new();
+                }
+                let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+                self.left_pane_text_lines(inner_width)
+            }
+            PaneFocus::Right => self
+                .visible_right_content(right_content)
+                .lines()
+                .map(str::to_string)
+                .collect(),
+        }
+    }
+
+    fn left_pane_text_lines(&self, inner_width: usize) -> Vec<String> {
+        let mut lines = vec![if self.control_selected == 0 {
+            "> work-leaf  command".to_string()
+        } else {
+            "  work-leaf  command".to_string()
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            lines.push(compact_agent_row(agent, selected, inner_width));
+            if !agent.modified_files.is_empty() {
+                lines.push(format!(
+                    "    files: {}",
+                    agent
+                        .modified_files
+                        .iter()
+                        .map(|path| path.display().to_string())
+                        .collect::<Vec<_>>()
+                        .join(", ")
+                ));
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    lines.push(format!(
+                        "    {label}: {}",
+                        agents.iter().map(AgentId::as_str).collect::<Vec<_>>().join(", ")
+                    ));
+                }
+            }
+        }
+        lines
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer, right_content: &str) {
+        if !self.mode.is_visual() {
+            return;
+        }
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.visual_text_lines(selection.pane, right_content);
+        if lines.is_empty() {
+            return;
+        }
+        let layout = self.layout();
+        let (x, y, width, height) = match selection.pane {
+            PaneFocus::Left => {
+                if layout.left_width == 0 {
+                    return;
+                }
+                (
+                    1,
+                    1,
+                    layout.left_width.saturating_sub(2).max(1),
+                    self.height.saturating_sub(3).max(1),
+                )
+            }
+            PaneFocus::Right => {
+                let right_x = if layout.left_width > 0 {
+                    layout.left_width
+                } else {
+                    0
+                };
+                (
+                    right_x.saturating_add(1),
+                    1,
+                    layout.right_width.saturating_sub(2).max(1),
+                    self.height.saturating_sub(3).max(1),
+                )
+            }
+        };
+        for (row, start, end) in selection_ranges(
+            &lines,
+            selection.anchor,
+            selection.cursor,
+            selection.kind,
+        ) {
+            if row >= usize::from(height) {
+                continue;
+            }
+            for column in start.min(usize::from(width))..end.min(usize::from(width)) {
+                buffer
+                    .get_mut(x.saturating_add(column as u16), y.saturating_add(row as u16))
+                    .modifier
+                    .insert(Modifier::REVERSED);
+            }
+        }
+    }

